import { apiFetch, ApiError, loadToken, clearToken, isSignedIn } from "./api.js";
import { el, clear, showMessage, formValues, whileBusy, formatTime } from "./ui.js";

const usernameEl = document.getElementById("username");
const signoutBtn = document.getElementById("signout");
const addForm = document.getElementById("add-form");
const todoList = document.getElementById("todo-list");
const pager = document.getElementById("pager");
const filterAll = document.getElementById("filter-all");
const filterOpen = document.getElementById("filter-open");
const filterDone = document.getElementById("filter-done");

let currentFilter = "all";
let currentOffset = 0;
let currentLimit = 20;
let currentUser = null;

function setActiveFilter(btn) {
  [filterAll, filterOpen, filterDone].forEach(b => b.classList.remove("active"));
  btn.classList.add("active");
}

async function loadUser() {
  try {
    const me = await apiFetch("/api/auth/me");
    currentUser = me;
    usernameEl.textContent = me.username;
  } catch (err) {
    if (err instanceof ApiError && err.status === 401) {
      location.href = "login.html";
    } else {
      showMessage("Failed to load user.", "error");
    }
  }
}

async function loadTodos() {
  try {
    const query = new URLSearchParams({ limit: currentLimit, offset: currentOffset });
    if (currentFilter !== "all") {
      query.set("done", currentFilter === "done" ? "true" : "false");
    }
    const resp = await apiFetch(`/api/todos?${query.toString()}`);
    renderTodos(resp.items, resp.total);
  } catch (err) {
    if (err instanceof ApiError) {
      showMessage(err.message, "error");
    } else {
      showMessage("Failed to load todos.", "error");
    }
  }
}

function renderTodos(items, total) {
  clear(todoList);
  if (items.length === 0) {
    const li = el("li", { class: "list-item muted" }, "No todos yet.");
    todoList.appendChild(li);
  } else {
    for (const todo of items) {
      const li = el("li", { class: "list-item" + (todo.done ? " done" : ""), "data-id": todo.id });
      const checkbox = el("input", { type: "checkbox", checked: todo.done, "aria-label": "Mark as done" });
      const titleSpan = el("span", { class: "title grow" }, todo.title);
      const updated = el("span", { class: "muted" }, formatTime(todo.updated_at));
      const renameBtn = el("button", { class: "secondary", "aria-label": "Rename" }, "Rename");
      const deleteBtn = el("button", { class: "danger", "aria-label": "Delete" }, "Delete");

      checkbox.addEventListener("change", () => toggleTodo(todo.id, checkbox.checked));
      renameBtn.addEventListener("click", () => renameTodo(todo.id, titleSpan));
      deleteBtn.addEventListener("click", () => deleteTodo(todo.id));

      li.append(checkbox, titleSpan, updated, renameBtn, deleteBtn);
      todoList.appendChild(li);
    }
  }
  renderPager(total);
}

function renderPager(total) {
  clear(pager);
  const totalPages = Math.ceil(total / currentLimit);
  const currentPage = Math.floor(currentOffset / currentLimit) + 1;

  if (totalPages <= 1) return;

  const prevBtn = el("button", { class: "secondary", disabled: currentPage === 1 }, "Previous");
  const nextBtn = el("button", { class: "secondary", disabled: currentPage === totalPages }, "Next");
  const pageInfo = el("span", { class: "muted", style: "align-self:center" }, `Page ${currentPage} of ${totalPages}`);

  prevBtn.addEventListener("click", () => {
    if (currentPage > 1) {
      currentOffset -= currentLimit;
